//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");

//채권 상세정보
scwin.vScrenID = "ULDINS91900.xml";
scwin.param1 = "";
scwin.param2 = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
/********************************************** 
 * 함수명   : ins_search
 * 설명       : 채권 상세정보
 ***********************************************/
scwin.ins_search = function() {
    //alert(param2); 
    var queryId = "";
    // 채권 상세팝업이다. 
    // param1 => 신청번호 STD_CD_APPL_ID
    // param2 => R 신청 / 마스터 구분 
    if (scwin.param2 == "R") {
        queryId = "lds.ins.common.select.readStdCdBndReqInfoViewInfo";
    } else {
        queryId = "lds.ins.common.select.readStdCdBndInfoViewInfo";
    }
    //alert(queryId); 
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=ULDINS91900_DETAIL_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=" + queryId + "&{P}param01=" + txb_pSTD_CD_APPL_ID.getValue();
    dts_detail.DataID = encodeURI(url);
    dts_detail.reset();

    // CALL		
    if (scwin.param2 == "R") {
        queryId = "lds.ins.common.select.readStdCdBndReqCallExerInfoViewInfo";
    } else {
        queryId = "lds.ins.common.select.readStdCdBndCallExerInfoViewInfo";
    }
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=STDCDBNDCALLEXERINFO_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=" + queryId + "&{P}param01=" + txb_pSTD_CD_APPL_ID.getValue();
    dts_List.DataID = encodeURI(url);
    dts_List.reset();

    // PUT
    if (scwin.param2 == "R") {
        queryId = "lds.ins.common.select.readStdCdBndReqPutExerInfoViewInfo";
    } else {
        queryId = "lds.ins.common.select.readStdCdBndPutExerInfoViewInfo";
    }
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=STDCDBNDPUTEXERINFO_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=" + queryId + "&{P}param01=" + txb_pSTD_CD_APPL_ID.getValue();
    dts_List1.DataID = encodeURI(url);
    dts_List1.reset();


    //종목별자산관련
    if (scwin.param2 == "R") {
        queryId = "lds.ins.common.select.readStdCdBndReqAsstInfoViewInfo";
    } else {
        queryId = "lds.ins.common.select.readStdCdBndAsstInfoViewInfo";
    }
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=STDCDBNDASSTINFO_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=" + queryId + "&{P}param01=" + txb_pSTD_CD_APPL_ID.getValue();
    dts_List2.DataID = encodeURI(url);
    dts_List2.reset();

    //종목별신용평가
    if (scwin.param2 == "R") {
        queryId = "lds.ins.common.select.readStdCdBndReqCreditValuInfoViewInfo";
    } else {
        queryId = "lds.ins.common.select.readStdCdBndCreditValuInfoViewInfo";
    }
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=STDCDBNDCREDITVALUINFO_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=" + queryId + "&{P}param01=" + txb_pSTD_CD_APPL_ID.getValue();
    dts_List3.DataID = encodeURI(url);
    dts_List3.reset();


    //채권지급이자
    if (scwin.param2 == "R") {
        queryId = "lds.ins.common.select.readStdCdBndReqPayIntInfoViewInfo";
    } else {
        queryId = "lds.ins.common.select.readStdCdBndPayIntInfoViewInfo";
    }
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=STDCDBNDPAYINTINFO_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=" + queryId + "&{P}param01=" + txb_pSTD_CD_APPL_ID.getValue();
    dts_List4.DataID = encodeURI(url);
    dts_List4.reset();


    //채권이자율변경일자
    if (scwin.param2 == "R") {
        queryId = "lds.ins.common.select.readStdCdBndReqBditrtChddInfoViewInfo";
    } else {
        queryId = "lds.ins.common.select.readStdCdBndBditrtChddInfoViewInfo";
    }
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=STDCDBNDBDITRTCHDDINFO_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=" + queryId + "&{P}param01=" + txb_pSTD_CD_APPL_ID.getValue();
    dts_List5.DataID = encodeURI(url);
    dts_List5.reset();


    //채권인수기관
    if (scwin.param2 == "R") {
        queryId = "lds.ins.common.select.readStdCdBndReqUdinstInfoViewInfo";
    } else {
        queryId = "lds.ins.common.select.readStdCdBndUdinstInfoViewInfo";
    }
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=STDCDBNDUDINSTINFO_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=" + queryId + "&{P}param01=" + txb_pSTD_CD_APPL_ID.getValue();
    dts_List6.DataID = encodeURI(url);
    dts_List6.reset();
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.stf.showObj(label_177, false);
    $c.stf.showObj(txb_pSTD_CD_APPL_ID, false);
    $c.stf.showObj(txb_UP_PARTC_RTO, false);
    $c.stf.showObj(txb_FNC_ULY_TP_CD, false);
    $c.stf.showObj(txb_RGHT_TP_CD, false);
    $c.stf.showObj(txb_ULY_CONTN, false);
    $c.stf.showObj(txb_MAX_EARNG_VAL, false);
    $c.stf.showObj(txb_MAX_LOSS_RT, false);
    $c.stf.showObj(txb_PRINC_GRT_RT, false);
    $c.stf.showObj(txb_MAX_YD, false);
    $c.stf.showObj(txb_MAX_LOSS_VAL, false);
    var arrPar = new Array();
    var parentWin = $c.frame.path("../");
    var fn_GetPar = parentWin.fn_GetParam;
    if (fn_GetPar != undefined) {
        fn_GetPar(arrPar);
        txb_pSTD_CD_APPL_ID.setValue(((arrPar.length >= 1) && (arrPar[0] != undefined) ? arrPar[0] : ""));
        scwin.param2 = ((arrPar.length >= 1) && (arrPar[1] != undefined) ? arrPar[1] : "");
        scwin.ins_search();
    }
    tab_UsrInfo.setSelectedTabIndex(1);

    //신청/처리에 따라 pcbo여부 가리기, SRI채권구분 text변경
    if (scwin.param2 == "R") {
        $c.stf.showObj(label_29, true);
        $c.stf.showObj(txb_PCBO_YN, true);
        $c.stf.showObj(label_31, true);
        $c.stf.showObj(label_32, false);
    } else {
        $c.stf.showObj(label_29, false);
        $c.stf.showObj(txb_PCBO_YN, false);
        $c.stf.showObj(label_31, false);
        $c.stf.showObj(label_32, true);
    }
};
scwin.dts_detail_OnLoadError = function() {
    $c.stf.alert_error(dts_detail);
};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_detail_OnLoadCompleted = function(rowcount) {
    //alert('dts_detail.OnLoadCompleted('+rowcount+')');

};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List1_OnLoadError = function() {
    $c.stf.alert_error(dts_List1);
};
scwin.dts_List2_OnLoadError = function() {
    $c.stf.alert_error(dts_List2);
};
scwin.dts_List3_OnLoadError = function() {
    $c.stf.alert_error(dts_List3);
};
scwin.dts_List4_OnLoadError = function() {
    $c.stf.alert_error(dts_List4);
};
scwin.dts_List5_OnLoadError = function() {
    $c.stf.alert_error(dts_List5);
};
scwin.dts_List6_OnLoadError = function() {
    $c.stf.alert_error(dts_List6);
};
